import { expect, type Page, type APIRequestContext, type TestInfo, type Locator } from '@playwright/test';
import { randomUUID, createHash } from 'node:crypto';
import { writeFile } from 'node:fs/promises';
import { blankContent, blankRequirement } from '@/domain/tasks/types';
import { blankDraft } from '@/domain/submissions/types';
import type { CorrectionWorkspace, ReviewTarget, BatchDraftInput } from '@/server/corrections/contracts';
import type { SubmissionWorkspace, SubmissionSnapshot, UploadResult } from '@/server/submissions/contracts';
import type { ProductDetail } from '@/server/products/service';
export const ctx = 'ctx-jp-a-luna', password = 'Demo-Hale-2026!', canary = 'PRIVATE_G10_UI_ORIGINAL_CANARY';
export const png = () => Buffer.from('iVBORw0KGgoAAAANSUhEUgAAAAEAAAABCAQAAAC1HAwCAAAAC0lEQVR42mP8/x8AAwMCAO+a+ZkAAAAASUVORK5CYII=', 'base64');
export async function login(page: Page, email = 'admin@example.test') { await page.context().clearCookies(); await page.goto('/login'); await page.getByRole('textbox', { name: '이메일', exact: true }).fill(email); await page.getByLabel('비밀번호', { exact: true }).fill(password); await page.getByRole('button', { name: '로그인', exact: true }).click(); await expect(page).toHaveURL(/\/$/); }
export async function mutate(r: APIRequestContext, url: string, data: unknown, method = 'POST') { const token = await (await r.get('/api/auth/csrf')).json(); return r.fetch(url, { method, data, headers: { Origin: `http://127.0.0.1:${process.env.E2E_PORT}`, 'X-CSRF-Token': token.csrfToken } }); }
export async function getWorkspace(page: Page, id: string): Promise<CorrectionWorkspace> { const r = await page.request.get(`/api/corrections?taskId=${id}`); expect(r.status()).toBe(200); return r.json(); }
export async function create(page: Page) { await login(page); const content = blankContent(); content.title = `수정 검토 합성 ${randomUUID().slice(0, 8)}`; content.description = '공개 수정 검토 UI 합성 업무'; content.deadline.responsibleUserId = 'user-gsg'; content.requirements = [{ ...blankRequirement('answer', 'long_text'), label: '공통 답변' }]; const r = await mutate(page.request, '/api/tasks', { category: 'spot', content, targets: [{ contextId: ctx, ownerId: 'user-gsg', assigneeId: 'user-luna', coAssigneeIds: ['user-co'], productIds: ['product-serum'] }], idempotencyKey: randomUUID() }); expect(r.status()).toBe(201); const id = (await r.json()).ids[0] as string; const t = await (await page.request.get(`/api/tasks/${id}`)).json(); expect((await mutate(page.request, `/api/tasks/${id}`, { command: 'publish', expectedRevision: t.task.revision, idempotencyKey: randomUUID() })).status()).toBe(200); return id; }
export async function produce(page: Page, id: string, label = '원본 v1'): Promise<SubmissionSnapshot> { let w: SubmissionWorkspace = await (await page.request.get(`/api/tasks/${id}/submissions`)).json(); const csrf = await (await page.request.get('/api/auth/csrf')).json(); const r = await page.request.post(`/api/tasks/${id}/submission-files?requestId=${w.request.id}`, { headers: { Origin: `http://127.0.0.1:${process.env.E2E_PORT}`, 'X-CSRF-Token': csrf.csrfToken }, multipart: { files: { name: label + '.png', mimeType: 'image/png', buffer: png() }, clientItemIds: randomUUID() } }); expect(r.status()).toBe(200); const f = (await r.json()).items[0] as UploadResult; expect(f.state).toBe('ready'); if (f.state !== 'ready')
    throw Error('upload failed'); const p: ProductDetail = await (await page.request.get(`/api/products/product-serum?context=${ctx}`)).json(); const content = { ...blankDraft(), answers: [{ requestId: w.request.id, requirementKey: 'answer', productId: null, type: 'long_text', input: { text: label } }], artifacts: [{ fileVersionId: f.file.id, role: 'review_copy', answer: null }], productSelections: [{ productId: p.productId, expectedCommonRevision: p.commonRevision, expectedContextRevision: p.contextRevision, bindingIds: [], retailPriceVersionId: null, asOfDate: '2026-09-21' }] }; expect((await mutate(page.request, `/api/tasks/${id}/submission-draft`, { command: 'save', baseRequestId: w.request.id, expectedDraftRevision: w.draft?.revision ?? 0, content, idempotencyKey: randomUUID() })).status()).toBe(200); w = await (await page.request.get(`/api/tasks/${id}/submissions`)).json(); const submitted = await mutate(page.request, `/api/tasks/${id}/submissions`, { baseRequestId: w.request.id, expectedDraftRevision: w.draft!.revision, expectedTaskRevision: w.taskRevision, mode: 'full', idempotencyKey: randomUUID() }); expect(submitted.status()).toBe(201); return (await page.request.get(`/api/submissions/${(await submitted.json()).ids[0]}`)).json(); }
export const target = (v: SubmissionSnapshot): ReviewTarget => ({ taskId: v.taskId, submissionId: v.id, requestId: v.requestId, submissionContentHash: v.contentHash, answer: null, fileVersionIds: v.files.map(f => f.id), productUseIds: v.products.map(p => p.id), location: { page: '2', locator: '엠블럼·하단 문구' } });
export async function seed(page: Page) { const id = await create(page); await login(page, 'luna@example.test'); const v1 = await produce(page, id); await login(page); return { id, v1 }; }
export async function open(page: Page, id: string) { await page.goto(`/tasks/${id}/corrections?context=${ctx}`); await expect(page.getByRole('navigation', { name: '수정 검토 화면' })).toBeVisible(); }
export const button = (p: Page | Locator, name: string) => p.getByRole('button', { name, exact: true });
export const field = (p: Page | Locator, name: string) => p.getByRole('textbox', { name, exact: true });
export async function settled(page: Page) { await expect(page.getByRole('status').filter({ hasText: '저장 결과를 확인했습니다.' })).toBeVisible(); await expect(page.getByRole('region', { name: '명령 복구' })).toHaveCount(0); }
export async function chooseTarget(scope: Locator, v: SubmissionSnapshot) { await scope.getByRole('combobox', { name: '대상 제출 버전', exact: true }).selectOption(v.id); await scope.getByRole('group', { name: '당시 상품 사용본', exact: true }).getByRole('checkbox').first().check(); await scope.getByRole('group', { name: '정확한 파일 버전', exact: true }).getByRole('checkbox').first().check(); await field(scope, '페이지').fill('2'); await field(scope, '위치 설명').fill('엠블럼·하단 문구'); }
export async function opinionUI(page: Page, v: SubmissionSnapshot, source = '기관 A 원문', original = canary) { await button(page, '내부 의견').click(); await button(page, '새 내부 의견').click(); const form = page.getByRole('group', { name: '새 의견 입력', exact: true }); await chooseTarget(form, v); await form.getByRole('combobox', { name: '의견 출처 유형', exact: true }).selectOption('external_opinion'); await field(form, '기관').fill('합성 기관 A'); await field(form, '검토자').fill('합성 검토자'); await field(form, '원문 출처').fill(source); await field(form, '의견 원문 · 내부 전용').fill(original); await form.getByLabel('의견 수신일', { exact: true }).fill('2026-09-21'); await button(form, '의견 버전 저장').click(); await settled(page); return (await getWorkspace(page, v.taskId)).staff!.opinions.find(o => o.versions[0].source.source === source)!; }
export async function batchUI(page: Page, v: SubmissionSnapshot, opinionIds: string[], count = 5) { await button(page, '공개 초안').click(); await field(page, '공개 제목').fill('공개 실행 요청'); await field(page, '공개 요약').fill('브랜드에 선별한 공개 설명입니다.'); for (let n = 1; n <= count; n++) {
    await button(page, '수정항목 추가').click();
    const item = page.getByRole('region', { name: `수정항목 ${n}`, exact: true });
    await chooseTarget(item, v);
    for (const id of opinionIds)
        await item.getByRole('checkbox', { name: new RegExp(id) }).check();
    await field(item, '공개 출처').fill('공개 기관 검토 요약');
    await field(item, '수정 내용').fill(`수정 ${n} · 엠블럼 ${n}`);
    await field(item, '수정 이유').fill('표시를 확인한 결과');
    await field(item, '브랜드 공개 설명').fill(`PUBLIC_G10_UI_SELECTED_${n}`);
} await button(page, '공개 초안 저장').click(); await settled(page); await button(page, '저장한 공개 초안 미리보기').click(); await expect(page.getByRole('region', { name: '브랜드 보기 미리보기' })).toBeVisible(); }
export async function command(page: Page, id: string, body: Record<string, unknown>) { const r = await mutate(page.request, '/api/corrections', { taskId: id, idempotencyKey: randomUUID(), ...body }); expect(r.status(), await r.text()).toBe(200); return (await r.json()).ids as string[]; }
export async function seedBatch(page: Page, v: SubmissionSnapshot, count = 2) { const t = target(v), o = (await command(page, v.taskId, { command: 'save_opinion', opinionId: null, expectedRevision: 0, opinion: { target: t, source: { kind: 'internal_review', reviewer: '검토자', source: '실제 의견' }, originalText: canary, internalFileVersionIds: [], receivedOn: null, conflictingOpinionVersionIds: [] } }))[1]; const d: BatchDraftInput = { title: '공개 묶음', summary: 'PUBLIC_G10_UI_SELECTED', mode: 'normal', pendingScopes: [], previousBatchVersionId: null, items: Array.from({ length: count }, (_, i) => ({ key: `item-${i}`, target: t, internalOpinionVersionIds: [o], publicSource: '공개 출처', change: `수정 ${i + 1}`, reason: '이유', publicDescription: 'PUBLIC_G10_UI_SELECTED', priority: 'normal', issue: 'correction' })) }; const id = (await command(page, v.taskId, { command: 'save_draft', draftId: null, expectedRevision: 0, draft: d }))[0]; await command(page, v.taskId, { command: 'publish', draftId: id, expectedRevision: 1 }); return (await getWorkspace(page, v.taskId)).batches[0]; }
export async function capture(page: Page, info: TestInfo, name: string) { await page.screenshot({ path: info.outputPath(name + '.png'), fullPage: true }); await writeFile(info.outputPath(name + '.html'), await page.content()); expect(await page.evaluate(() => document.documentElement.scrollWidth <= innerWidth)).toBe(true); }
export async function retain(page: Page, info: TestInfo) { await writeFile(info.outputPath('final-dom-private.html'), await page.content()); await page.screenshot({ path: info.outputPath('final-private.png'), fullPage: true }); }
export async function recordJSON(info: TestInfo, name: string, value: unknown) { await writeFile(info.outputPath(name + '.json'), JSON.stringify(value, null, 2)); }
export const hash = (b: Buffer) => createHash('sha256').update(b).digest('hex');
